import {replayRouletteWagers} from './roulette-wagers.mjs';
import {patchBoard} from './craps-wager-queue.mjs';
import {BETS,color,newRoulette,rouletteAct,rouletteTick,rouletteView,rouletteBots} from './roulette.mjs';
import {Roulette3D} from './roulette3d.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const COLORS=['#d9f080','#a3ccff','#f2a4dc','#ffba79','#a3e4c0','#d5b8ff','#fff0b0','#ff9595'];
export const ROULETTE_RULES='<p>美式双零轮盘：0、00、1–36，共 38 格，每格概率均为 1/38。虚拟筹码，无现金兑换。</p><p>下注不限时，由本轮发球者决定开始；发球 7 秒后封盘。多人每局轮换发球者。球落定后结算，下一局由玩家各自准备。</p><p>净赔付：单号 35:1；分注 17:1；三号 11:1；角注 8:1；六线 5:1；五号注 6:1；打 / 列 2:1；红黑、单双、大小 1:1。赢注另退本金；0 和 00 不属于红黑、单双、大小。</p><p>选择筹码后点击桌布直接下注。分注等组合通过下拉选项选择，桌布会高亮覆盖的号码。封盘前可撤回自己的下注。</p><a href="https://www.pacodeandbulletin.gov/secure/pacode/data/058/chapter617a/058_0617a.pdf" target="_blank" rel="noopener">标准轮盘规则与赔付依据</a>';
export class RouletteUI{
 constructor(host,{network,beep=()=>{},toast=()=>{}}){Object.assign(this,{host,network,beep,toast});this.amount=25;this.wagerQueue=[];this.wagerFlight=[];this.alive=true;this.selected='n17';this.q=s=>host.querySelector(s);document.body.classList.add('in-game');host.innerHTML=`<section class="roulette-room"><header class="rl-heading"><h1>美国轮盘 <small>0 / 00 · AMERICAN ROULETTE</small></h1><button data-exit>离开牌桌</button><button data-rules>规则</button><button data-full>全屏</button></header><div class="rl-status" aria-live="polite"></div><div class="rl-main"><div class="rl-wheel"><div class="rl-canvas"></div><div class="rl-outcome"></div></div><section class="rl-betting"><div class="rl-chips"><label class="custom-wager">下注金额<input data-custom-wager type="number" min="1" step="1" inputmode="numeric" value="25" aria-label="自定义下注金额"></label>${[5,10,25,100,500].map(n=>`<button data-chip="${n}" aria-pressed="${n===25}">${n}</button>`).join('')}<button data-remove-mode aria-pressed="false">撤回模式</button><span class="rl-sync" aria-live="polite"></span><button data-clear>撤回全部</button><button data-launch>由你发球</button></div><div class="rl-felt-scroll"><div class="rl-felt"></div></div><div class="rl-combo"><label>组合下注<select data-type><option value="split">分注 · 17:1</option><option value="street">三号 · 11:1</option><option value="corner">角注 · 8:1</option><option value="six">六线 · 5:1</option><option value="top">五号注 · 6:1</option></select></label><label>覆盖号码<select data-combination></select></label><button data-combo-bet>下注 25</button></div><div class="rl-selected"></div></section></div><section class="rl-players"></section><div class="rl-result" aria-live="polite"></div><dialog class="rl-rules"><h2>美式双零轮盘</h2>${ROULETTE_RULES}<button data-close-rules>返回牌桌</button></dialog></section>`;this.q('[data-exit]').onclick=network.exit;this.q('[data-rules]').onclick=()=>this.q('dialog').showModal();this.q('[data-close-rules]').onclick=()=>this.q('dialog').close();this.q('[data-full]').onclick=()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen().catch(()=>{});this.q('[data-launch]').onclick=()=>this.send('launch');this.q('[data-remove-mode]').onclick=()=>{this.removing=!this.removing;this.modeFeedback()};this.q('[data-clear]').onclick=()=>this.send('clear');this.q('[data-type]').onchange=()=>this.combos();this.q('[data-combination]').onchange=e=>{this.selected=e.target.value;this.render()};this.q('[data-combo-bet]').onclick=()=>this.bet(this.q('[data-combination]').value);host.querySelectorAll('[data-chip]').forEach(b=>b.onclick=()=>{this.amount=+b.dataset.chip;this.q('[data-custom-wager]').value=this.amount;host.querySelectorAll('[data-chip]').forEach(c=>c.setAttribute('aria-pressed',String(c===b)));this.modeFeedback()});this.q('[data-custom-wager]').oninput=e=>{this.amount=Number(e.target.value);host.querySelectorAll('[data-chip]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.chip===this.amount)));this.modeFeedback()};this.combos();try{this.scene=new Roulette3D(this.q('.rl-canvas'),{onSound:beep})}catch{this.q('.rl-canvas').innerHTML='<p class="rl-fallback">此浏览器无法显示 3D，轮盘结果仍会同步。</p>'}this.timer=setInterval(()=>this.clock(),100)
 }
 combos(){const type=this.q('[data-type]').value;this.q('[data-combination]').innerHTML=Object.values(BETS).filter(b=>b.type===type).map(b=>`<option value="${b.key}">${b.label}</option>`).join('');this.selected=this.q('[data-combination]').value;if(this.r)this.render()}
 now(){return Date.now()+(this.offset??0)}
 apply(r){const totals=r.game.players.map(p=>Object.values(p.bets).reduce((a,b)=>a+b,0));if(this.betTotals&&totals.some((v,i)=>i!==r.you&&v>this.betTotals[i]))this.beep('chips');this.betTotals=totals;this.authoritative=r;this.r=r;this.offset=r.serverNow-Date.now();this.replayPending();this.scene?.apply(r.game,this.offset,r.seats,r.you);this.render();this.clock()}
 modeFeedback(){const b=this.q('[data-remove-mode]');b.setAttribute('aria-pressed',String(!!this.removing));b.textContent=this.removing?'撤回中 · 点击区域':'撤回模式';this.q('[data-combo-bet]').textContent=this.removing?'撤回组合下注':'下注 '+(this.amount>0?this.amount:'');this.q('.roulette-room').classList.toggle('rl-removing',!!this.removing)}
 replayPending(){if(!this.authoritative)return;this.r=structuredClone(this.authoritative);for(const a of [...this.wagerFlight,...this.wagerQueue]){try{this.r.game=replayRouletteWagers(this.r.game,this.r.you,[a],this.now())}catch{break}}const wallet=document.querySelector('#wallet');if(wallet)wallet.textContent=this.r.game.players[this.r.you].bank.toLocaleString()}
 ackWagers(){this.wagerFlight=[]}
 async flushWagers(){if(!this.alive||!this.wagerQueue.length||this.wagerFlight.length)return;if(this.network.canSend&&!this.network.canSend()){this.wagerTimer=setTimeout(()=>this.flushWagers(),60);return}this.wagerFlight=this.wagerQueue.splice(0,32);try{await this.network.send({action:'betBatch',bets:this.wagerFlight})}catch(e){this.wagerFlight=[];this.wagerQueue=[];this.replayPending();this.toast(e.message||'下注未成功，请核对金额')}finally{this.wagerFlight=[];if(this.alive){this.replayPending();this.render();if(this.wagerQueue.length)this.wagerTimer=setTimeout(()=>this.flushWagers(),0)}}}
 async send(action,key){if(!this.r||!this.alive)return;if(['bet','remove','clear'].includes(action)){try{const a={action,key,amount:this.amount};this.r={...this.r,game:replayRouletteWagers(this.r.game,this.r.you,[a],this.now())};this.wagerQueue.push(a);const wallet=document.querySelector('#wallet');if(wallet)wallet.textContent=this.r.game.players[this.r.you].bank.toLocaleString();this.beep('chips');this.render();clearTimeout(this.wagerTimer);this.wagerTimer=setTimeout(()=>this.flushWagers(),60)}catch(e){this.toast(e.message)}return}if(this.pending)return;if(this.wagerQueue.length||this.wagerFlight.length){this.toast('下注正在确认，稍后即可发球');this.flushWagers();return}this.pending=true;try{await this.network.send({action,key,amount:this.amount})}catch(e){this.toast(e.message||'操作未成功，请重试')}finally{this.pending=false;this.clock()}}
 bet(key){this.selected=key;this.send(this.removing?'remove':'bet',key)}
 cell(key,style=''){const b=BETS[key],r=this.r;const bets=r.game.players.map((p,i)=>p.bets[key]?`<span style="--player:${COLORS[i]}" title="${esc(r.seats[i].name)}">${i+1}: ${p.bets[key]}</span>`:'').join('');return `<button class="rl-cell ${b.type==='straight'?color(b.label):''} ${this.selected===key?'selected':''} ${this.r.game.phase==='done'&&b.numbers.includes(r.game.pocket)?'won':''}" style="${style}" data-bet="${key}" aria-label="${esc(b.label)}，净赔付 ${b.pay} 比 1"><b>${esc(b.label)}</b><small>${bets}</small></button>`}
 render(){const r=this.r,g=r.game;let html=this.cell('n00','grid-column:1;grid-row:1 / span 2')+this.cell('n0','grid-column:1;grid-row:3');for(let col=0;col<12;col++)for(let row=0;row<3;row++)html+=this.cell('n'+(col*3+3-row),`grid-column:${col+2};grid-row:${row+1}`);for(let i=0;i<3;i++)html+=this.cell('col'+i,`grid-column:14;grid-row:${3-i}`);for(let i=0;i<3;i++)html+=this.cell('d'+i,`grid-column:${2+i*4} / span 4;grid-row:4`);['low','even','red','black','odd','high'].forEach((k,i)=>html+=this.cell(k,`grid-column:${2+i*2} / span 2;grid-row:5`));patchBoard(this.q('.rl-felt'),html);this.host.querySelectorAll('[data-bet]').forEach(b=>{b.onclick=()=>this.bet(b.dataset.bet);if(BETS[this.selected].numbers.includes(b.dataset.bet.slice(1))&&b.dataset.bet.startsWith('n'))b.classList.add('covered')});const selected=BETS[this.selected];this.q('.rl-selected').innerHTML=`<strong>${esc(selected.label)} · 净赔付 ${selected.pay}:1</strong><span>${g.players.map((p,i)=>p.bets[this.selected]?esc(r.seats[i].name)+' '+p.bets[this.selected]:'').filter(Boolean).join(' ／ ')||'此区域暂无下注'}</span><button data-remove>撤回我在此区的下注</button>`;this.q('[data-remove]').onclick=()=>this.send('remove',this.selected);this.q('.rl-players').innerHTML=r.seats.map((s,i)=>`<article style="--player:${COLORS[i]}"><strong>${i+1} · ${esc(s.name)}${i===r.you?'（你）':''}</strong><span class="player-chip-total">总筹码 ${Number(s.totalChips??(g.players[i].bank+(g.done?0:Object.values(g.players[i].bets).reduce((a,b)=>a+b,0)))).toLocaleString()}</span><span>已下注 ${g.done?0:Object.values(g.players[i].bets).reduce((a,b)=>a+b,0)} · 可用 ${g.players[i].bank}</span><div>${Object.entries(g.players[i].bets).map(([k,v])=>`<span>${esc(BETS[k].label)} <b>${v}</b></span>`).join('')||'<span>等待下注</span>'}</div></article>`).join('');this.q('.roulette-room').classList.toggle('rl-finished',g.done);this.q('.rl-result').innerHTML=g.done?`<div class="rl-result-summary"><strong>落点 ${g.pocket} · 本局结算</strong><p>${r.seats.map((s,i)=>esc(s.name)+' '+(g.players[i].delta>=0?'+':'')+g.players[i].delta).join('　')}</p><span class="rl-next-help"></span></div><div class="rl-result-actions"><button data-next>开始下一局</button><button data-result-exit>离开牌桌</button></div>`:'';if(g.done){this.q('[data-next]').onclick=()=>this.next();this.q('[data-result-exit]').onclick=()=>this.network.exit()}this.clock()}
 clock(){if(document.hidden||!this.r)return;const r=this.r,g=r.game,now=this.now(),open=(g.closeAt===null||now<g.closeAt)&&!g.done,launched=g.launchAt!==null&&now>=g.launchAt,landed=g.landAt!==null&&now>=g.landAt;const launcher=this.q('[data-launch]');if(launcher){launcher.disabled=launched||g.done||g.roller!==r.you||this.pending;launcher.textContent=launched?'本轮已发球':g.roller===r.you?'由你发球 ↗':'等待 '+(r.seats[g.roller]?.name??'发球者')}this.q('.rl-status').textContent=open?(launched?'球已抛出 · '+Math.max(0,Math.ceil((g.closeAt-now)/1000))+' 秒后截止下注':'自由下注 · '+(r.seats[g.roller]?.name??'玩家')+' 决定何时发球'):(landed?'球已落定':'停止下注 · 等待球落定');this.q('.roulette-room').classList.toggle('rl-locked',!open);this.q('.rl-outcome').textContent=landed&&g.pocket!==null?'落点 '+g.pocket:launched?'轮盘旋转中':'';this.host.querySelectorAll('[data-bet],[data-combo-bet],[data-clear],[data-remove],[data-custom-wager],[data-remove-mode]').forEach(b=>b.disabled=!open||this.pending);this.q('.rl-sync').textContent=this.wagerQueue.length||this.wagerFlight.length?'正在确认…':'';const focus=g.closeAt!==null&&now>=g.closeAt&&now<g.endAt;const room=this.q('.roulette-room');if(focus!==!!this.focused){if(focus)this.bettingScroll=room.scrollTop;room.classList.toggle('rl-focus',focus);room.scrollTop=focus?0:(this.bettingScroll??0);this.focused=focus;}if(landed&&g.pocket!==null){const tone={red:'红',black:'黑',green:'绿'}[color(g.pocket)],zero=g.pocket==='0'||g.pocket==='00';this.q('.rl-outcome').textContent='落点 '+g.pocket+' · '+tone+(zero?'':' · '+(Number(g.pocket)%2?'单':'双')+' · '+(Number(g.pocket)<=18?'小':'大'))+(focus?' ｜ '+Math.max(1,Math.ceil((g.endAt-now)/1000))+' 秒后返回结算':'');}const next=this.q('[data-next]');if(g.done&&next){const seconds=Math.max(0,Math.ceil(((r.reviewUntil??0)-now)/1000)),ready=r.seats[r.you].ready;next.disabled=ready||seconds>0||!!this.nextPending;next.textContent=this.nextPending?'正在准备…':seconds?'查看结算 · '+seconds+' 秒':ready?'已准备，等待其他玩家':r.solo?'开始下一局':'准备下一局';const humans=r.seats.filter(s=>!s.bot);this.q('.rl-next-help').textContent=r.solo?'点击开始下一局，重新开放不限时下注。':humans.filter(s=>s.ready).length+' / '+humans.length+' 人已准备 · 每位玩家各自点击准备，全部准备后开始。'}const phase=landed?'landed':launched?'launched':'bets';if(!this.scene&&this.lastPhase&&phase!==this.lastPhase)this.beep(landed?'win':'deal');this.lastPhase=phase}
 async next(){const r=this.r;if(this.nextPending||!r?.game.done||r.seats[r.you].ready||this.now()<(r.reviewUntil??0))return;this.nextPending=true;this.clock();try{await this.network.next()}catch(e){this.toast(e.message||'准备失败，请重试')}finally{this.nextPending=false;this.clock()}}
 destroy(){this.alive=false;clearTimeout(this.wagerTimer);this.wagerQueue=[];clearInterval(this.timer);this.scene?.destroy()}
}
export class SoloRoulette{
 constructor(host,{bank,onBank,onExit,toast,beep}){Object.assign(this,{bank,onBank,onExit,toast});this.round=0;this.seats=[{name:'你',bot:false,bank,ready:false}];this.ui=new RouletteUI(host,{beep,toast,network:{send:d=>this.send(d),next:()=>this.start(),exit:()=>this.exit()}});this.start();this.timer=setInterval(()=>{if(rouletteTick(this.game))this.emit()},100)}
 start(){if(this.game&&!this.game.done)return;if(this.game&&Date.now()<this.game.endAt+1800)return;this.seats.forEach(s=>{if(s.bank<5)s.bank=2000});this.round++;this.game=newRoulette(this.seats.map(s=>s.bank));rouletteBots(this.game,this.seats);this.emit()}
 emit(){this.seats.forEach((s,i)=>s.bank=this.game.players[i].bank);this.bank=this.seats[0].bank;this.onBank(this.bank);this.ui.apply({mode:'roulette',solo:true,you:0,seats:this.seats,round:this.round,serverNow:Date.now(),reviewUntil:this.game.endAt+1800,status:this.game.done?'roundEnd':'playing',game:rouletteView(this.game)})}
 async send(d){if(d.action==='betBatch'){this.game=replayRouletteWagers(this.game,0,d.bets,Date.now());this.ui.ackWagers()}else rouletteAct(this.game,0,d.action,d.key,d.amount);this.emit()}
 exit(){if(!this.game.done&&Object.keys(this.game.players[0].bets).length&&!confirm('离桌会放弃本局已下注筹码，确定离开？'))return;this.destroy();this.onExit()}
 destroy(){clearInterval(this.timer);this.ui.destroy()}
}
